A("MOLE_WATER_REST_AREAS_COOLING_WORKPLACES","Ensure adequate drinking water, rest areas and cooling of work places","public",U,TR,PL,1,"Ensuring adequate drinking water facilities and making provision for rest areas and cooling of work places","high",SH),
